          return a[ordenacao.campo].localeCompare(b[ordenacao.campo]);
        } else {
          return b[ordenacao.campo].localeCompare(a[ordenacao.campo]);
        }
      });
    }
    return usuarios;
  };

  return (
    <table>
      <thead>
        <tr>
          <th onClick={() => handleClicarCabecalho('nome')}>Nome</th>
          <th onClick={() => handleClicarCabecalho('email')}>E-mail</th>
          <th onClick={() => handleClicarCabecalho('telefone')}>Telefone</th>
        </tr>
      </thead>
      <tbody>
        {usuariosOrdenados().map((usuario) => (
          <Usuario key={usuario.nome} usuario={usuario} />
        ))}
      </tbody>
    </table>
  );
}

