import React, { useState } from 'react';

const TabelaUsuarios = () => {
  const [usuarios, setUsuarios] = useState([
    { nome: 'João', email: 'joao@example.com', dataCadastro: '2022-01-01' },
    { nome: 'Maria', email: 'maria@example.com', dataCadastro: '2022-02-01' },
    { nome: 'Pedro', email: 'pedro@example.com', dataCadastro: '2022-03-01' },
  ]);

  const [ordenacao, setOrdenacao] = useState({
    campo: '',
    ordem: 'asc',
  });

  const handleClicarCabecalho = (campo) => {
    if (ordenacao.campo === campo) {
      setOrdenacao((prevOrdenacao) => ({ ...prevOrdenacao, ordem: prevOrdenacao.ordem === 'asc' ? 'desc' : 'asc' }));
    } else {
      setOrdenacao({ campo, ordem: 'asc' });
    }
  };

  const ordenarUsuarios = (usuarios, campo, ordem) => {
    return usuarios.sort((a, b) => {
      if (ordem === 'asc') {
        return a[campo].localeCompare(b[campo]);
      } else {
        return b[campo].localeCompare(a[campo]);
      }
    });
  };

  const usuariosOrdenados = ordenarUsuarios(usuarios, ordenacao.campo, ordenacao.ordem);

  return (
    <table>
      <thead>
        <tr>
          <th onClick={() => handleClicarCabecalho('nome')}>Nome</th>
          <th onClick={() => handleClicarCabecalho('email')}>E-mail</th>
          <th onClick={() => handleClicarCabecalho('dataCadastro')}>Data de Cadastro</th>
