  const [colunasOrdem, setColunasOrdem] = useState({});

  const ordenarColuna = (coluna) => {
    if (!colunasOrdem[coluna]) {
      setColunasOrdem((prevColunasOrdem) => ({ ...prevColunasOrdem, [coluna]: 'asc' }));
      setUsuariosOrdenados((prevUsuariosOrdenados) =>
        prevUsuariosOrdenados.sort((a, b) => a[coluna].localeCompare(b[coluna]))
      );
    } else if (colunasOrdem[coluna] === 'asc') {
      setColunasOrdem((prevColunasOrdem) => ({ ...prevColunasOrdem, [coluna]: 'desc' }));
      setUsuariosOrdenados((prevUsuariosOrdenados) =>
        prevUsuariosOrdenados.sort((a, b) => b[coluna].localeCompare(a[coluna]))
      );
    } else {
      setColunasOrdem((prevColunasOrdem) => ({ ...prevColunasOrdem, [coluna]: 'asc' }));
      setUsuariosOrdenados((prevUsuariosOrdenados) =>
        prevUsuariosOrdenados.sort((a, b) => a[coluna].localeCompare(b[coluna]))
      );
    }
  };

  return (
