Aqui está um exemplo de como criar um modal de confirmação em JavaScript puro:
```javascript
// Crie um objeto para armazenar as configurações do modal
const modalConfig = {
  title: 'Confirmação',
  message: 'Você deseja realmente deletar este item?',
  confirmText: 'Confirmar',
  cancelText: 'Cancelar'
};

// Função para criar o modal
function createModal(config) {
  const modal = document.createElement('div');
  modal.classList.add('modal');

  const header = document.createElement('h2');
  header.textContent = config.title;
  modal.appendChild(header);

  const message = document.createElement('p');
  message.textContent = config.message;
  modal.appendChild(message);

  const buttonsContainer = document.createElement('div');
  buttonsContainer.classList.add('buttons-container');

  const confirmButton = document.createElement('button');
  confirmButton.textContent = config.confirmText;
  confirmButton.addEventListener('click', () => {
    // Aqui você pode adicionar a lógica para deletar o item
    console.log('Item deletado com sucesso!');
    modal.remove();
  });
  buttonsContainer.appendChild(confirmButton);

  const cancelButton = document.createElement('button');
  cancelButton.textContent = config.cancelText;
  cancelButton.addEventListener('click', () => {
    modal.remove();
  });
  buttonsContainer.appendChild(cancelButton);

  modal.appendChild(buttonsContainer);

  return modal;
}

// Função para abrir o modal
function openModal(config) {
  const modal = createModal(config);
  document.body.appendChild(modal);
}

// Exemplo de uso:
openModal(modalConfig);
```
